/**
 * Handcrafted response data interfaces.
 * These describe the actual shape of `data` inside the { success, data, error } envelope.
 * The envelope itself is generated by openapi-typescript.
 */

// ── Auth ────────────────────────────────────────────

export interface LoginData {
  access_token: string
  refresh_token: string
  user: {
    id: string
    email: string
    role: string
    customer_id: string
    created_at: string
  }
}

export interface RegisterData {
  user: {
    id: string
    email: string
    role: string
    customer_id: string
    created_at: string
  }
}

export interface RefreshData {
  access_token: string
  refresh_token: string
}

export interface MeData {
  user: {
    id: string
    email: string
    role: string
    customer_id: string
    created_at: string
  }
}

// ── Customer ────────────────────────────────────────

export interface CustomerItem {
  id: string
  company_name: string
  email: string
  vat_number: string
  line1: string
  line2?: string
  city: string
  postal_code?: string
  country: string
  status: string
  created_at: string
}

export interface CustomerQueueData {
  customers: CustomerItem[]
  total: number
  page: number
  page_size: number
}

export interface CustomerDetailData {
  customer: CustomerItem
}

export interface InviteData {
  invite_link: string
  expires_at: string
}

export interface RegisterCustomerData {
  customer_id: string
  message: string
}

export interface DashboardData {
  total_inbounds: number
  pending_inbounds: number
  active_stock_items: number
  recent_activity: Array<{
    id: string
    action: string
    timestamp: string
  }>
}

// ── Inbound ─────────────────────────────────────────

export interface InboundItem {
  id: string
  customer_id: string
  customer_name: string
  status: string
  expected_date: string
  notes?: string
  created_at: string
  items: InboundItemDetail[]
}

export interface InboundItemDetail {
  sku: string
  quantity_declared: number
  quantity_received?: number
  dimensions?: string
  weight?: number
}

export interface InboundQueueData {
  inbounds: InboundItem[]
  page_token?: string
  page_size: number
}

export interface CreateInboundData {
  id: string
  message: string
}

export interface InspectData {
  inspection_id: string
  passed: boolean
  notes?: string
}

export interface FlagData {
  flag_id: string
  reason: string
}
